import pytest

from string_utils import slugify


def test_slugify_mixed_case_and_punctuation():
    # Uppercase letters become lowercase; punctuation becomes hyphens
    assert slugify("Hello, World!") == "hello-world"


def test_slugify_multiple_consecutive_hyphens_collapsed():
    # Multiple non-alphanumeric characters in a row collapse to a single hyphen
    assert slugify("a!!!b") == "a-b"


def test_slugify_all_non_alnum_returns_empty():
    # Every character is non-alphanumeric, so the result is empty
    assert slugify("!!!") == ""


def test_slugify_numbers_preserved():
    # Digits are alphanumeric and must be preserved
    assert slugify("abc123") == "abc123"


def test_slugify_single_char_alnum():
    # A single alphanumeric character is returned unchanged
    assert slugify("a") == "a"


def test_slugify_single_upper_char_lowercased():
    # A single uppercase letter is lowercased
    assert slugify("A") == "a"


def test_slugify_leading_trailing_non_alnum_stripped():
    # Leading and trailing non-alphanumeric characters are stripped
    assert slugify("...hello...") == "hello"


def test_slugify_unicode_letters_preserved():
    # Unicode letters are alphanumeric via isalnum() and are preserved
    assert slugify("café") == "café"


def test_slugify_unicode_upper_lowercased():
    # Unicode uppercase letters are lowercased
    assert slugify("CAFE") == "cafe"


def test_slugify_underscore_replaced():
    # Underscore is non-alphanumeric and replaced with hyphen
    assert slugify("hello_world") == "hello-world"


def test_slugify_long_run_of_special_chars():
    # A long run of special characters collapses to a single hyphen
    assert slugify("a" + "!" * 100 + "b") == "a-b"


def test_slugify_only_hyphens_returns_empty():
    # Input that is only hyphens results in empty string after strip
    assert slugify("---") == ""


def test_slugify_tab_and_newline_replaced():
    # Tab and newline are non-alphanumeric
    assert slugify("a\tb\nc") == "a-b-c"


def test_slugify_space_replaced_with_hyphen():
    # Spaces are non-alphanumeric
    assert slugify("a b c") == "a-b-c"

import pytest

from string_utils import slugify


def test_slugify_boundary_single_space():
